DO $$
BEGIN

    UPDATE appointments
    SET status = 'high_risk'
    WHERE previous_no_shows >= 3 AND status = 'scheduled';

    UPDATE appointments
    SET cancellation_fee =  base_fee  * 0.15
    WHERE status = 'cancelled' AND (cancellation_fee IS NULL OR cancellation_fee = 0);

    UPDATE appointments
    SET cancellation_fee = 0
    WHERE status = 'cancelled' AND previous_no_shows >= 3;

END $$;

SELECT * FROM appointments ORDER BY appointment_id;
